CREATE POLICY "PDFs da revista sao publicos" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'revistas');
CREATE POLICY "Admin envia PDF da revista" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'revistas' AND public.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admin atualiza PDF da revista" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'revistas' AND public.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (bucket_id = 'revistas' AND public.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admin remove PDF da revista" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'revistas' AND public.has_role(auth.uid(), 'admin'::app_role));